  const extra = `<div class="field"><label for="ab-l">Learner</label><select class="select" id="ab-l">${elig.map(l => `<option value="${l.id}">${l.name} (${l.id})</option>`).join('')}</select><span class="hint">Only learners not enrolled in any other active batch are listed.</span></div>`;
